                 		resp.put("message","Account From is required.");
                 		return resp;
                 	}
                 	if(account_to == null)
                 	{
                 		resp.put("message","Account To is required.");
                 		return resp;
                 	}
                 	if(amount_transferred <= 0)
                 	{
                 		resp.put("message","Amount Transferred must be greater than zero.");
                 		return resp;
                 	}
                 	if(transfer_date == null)
                 	{
                 		transfer_date = zoho.currenttime;
                 	}
                 	transfer_rec = Transfer_Funds[Source_Record_ID == source_record_id];
                 	if(transfer_rec.ID != null)
                 	{
                 		transfer_rec.Transfer_Date=transfer_date;
                 		transfer_rec.Amount_Transferred=amount_transferred;
                 		transfer_rec.Account_From=account_from;
                 		transfer_rec.Display_Name_Account_From=display_account_from;
                 		transfer_rec.Transfer_Reference=transfer_reference;
                 		transfer_rec.Transfer_Description=transfer_description;
                 		transfer_rec.Account_To=account_to;
                 		transfer_rec.Display_Name_Account_To=display_account_to;
                 		transfer_rec.Receive_Reference=receive_reference;
                 		transfer_rec.Receive_Description=receive_description;
                 		resp.put("ok",true);
                 		resp.put("created",false);
                 		resp.put("transfer_fund_id",transfer_rec.ID);
                 		resp.put("message","Transfer Funds record updated.");
                 		return resp;
                 	}
                 	new_transfer_id = insert into Transfer_Funds
                 	[
                 		Transfer_Date=transfer_date
                 		Amount_Transferred=amount_transferred
                 		Account_From=account_from
                 		Display_Name_Account_From=display_account_from
                 		Transfer_Reference=transfer_reference
                 		Transfer_Description=transfer_description
                 		Account_To=account_to
                 		Display_Name_Account_To=display_account_to
                 		Receive_Reference=receive_reference
                 		Receive_Description=receive_description
                 		Source_Record_ID=source_record_id
                 		Added_User=zoho.loginuser
                 	];
                 	resp.put("ok",true);
                 	resp.put("created",true);
                 	resp.put("transfer_fund_id",new_transfer_id);
                 	resp.put("message","Transfer Funds record created.");
                 	return resp;
